"""Run the submission entry over pipes (no supervision profile needed here)."""
import json, os, subprocess, sys, pathlib

CAND = '/workspace/submission/main.py'

def run_bytes(data: bytes, policy=False, timeout=600):
    env = {'PATH': os.environ.get('PATH', '/usr/local/bin:/usr/bin:/bin'),
           'LANG': 'C.UTF-8', 'HOME': '/workspace',
           'TMPDIR': os.environ.get('TMPDIR', '/workspace/tmp'),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONHASHSEED': '0'}
    kw = {}
    if policy:
        sys.path.insert(0, '/workspace')
        from candidate_policy import candidate_setup
        kw['preexec_fn'] = candidate_setup
    p = subprocess.run([sys.executable, '-B', CAND], input=data, stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, env=env, timeout=timeout, **kw)
    return p

def run_request(req, policy=False):
    data = json.dumps(req, separators=(',', ':')).encode()
    p = run_bytes(data, policy)
    if p.returncode != 0:
        raise RuntimeError('nonzero exit %d stderr=%r' % (p.returncode, p.stderr[:2000]))
    return json.loads(p.stdout.decode()), p

def run_raw(text, policy=False):
    p = run_bytes(text.encode(), policy)
    if p.returncode != 0:
        raise RuntimeError('nonzero exit %d stderr=%r' % (p.returncode, p.stderr[:2000]))
    return json.loads(p.stdout.decode()), p
