sys.path.insert(0, '/workspace/dev')
import topo

SMALL = [
    ['leaf-spine', 3, 2], ['leaf-spine', 4, 1], ['leaf-spine', 6, 3],
    ['clos', 4, 'tor', 1], ['clos', 4, 'pod', 1], ['clos', 4, 'tor', 0], ['clos', 6, 'pod', 0],
