]

def gen_session(rng, big=False):
    spec = rng.choice(SMALL)
    n, tmpl, dom = topo.build(spec)
    T = len(tmpl)
    G = rng.randint(1, 6 if not big else 40)
    D = rng.randint(0, 14 if not big else 300)
    by_domain = {}
    for i, d in enumerate(dom):
        by_domain.setdefault(d, []).append(i)
    domains = sorted(by_domain)
    groups = []
    tasks = []
    group_domains = []
    for g in range(G):
        quota = rng.choice([0, 1, 1, 2, 3, 5, 8, 12])
        budget = rng.choice([1, 2, 5, 100, 10**6, 10**9])
        groups.append([quota, budget])
        if domains and rng.random() < 0.85:
            group_domains.append((rng.choice(domains), rng.randint(0, 4)))
        else:
            group_domains.append(None)
    for t in range(D):
        g = rng.randrange(G)
        gd = group_domains[g]
        if gd is None or rng.random() < 0.05:
            tpl = rng.randrange(T)
        else:
            tpl = rng.choice(by_domain[gd[0]])
        cls = gd[1] if (gd is not None and rng.random() < 0.9) else rng.randint(0, 4)
        tasks.append([tpl, g, rng.randint(1, 30), cls, 1 if rng.random() < 0.3 else 0])
    # capacities: exact usage + slack, computed with a simple union
    usage = [0]*n
    foot = [set() for _ in range(G)]
    for (tpl, g, w, c, p) in tasks:
        foot[g] |= set(tmpl[2] for tmpl in [tmpl_item(tmpl)]) if False else set()
    # recompute properly
    foot = [set() for _ in range(G)]
    for (tpl, g, w, c, p) in tasks:
        foot[g] |= set(t[2] for t in [tmpl[0]]) if False else set()
    fps = [set(f) for (s, d, f) in tmpl]
    foot = [set() for _ in range(G)]
    for (tpl, g, w, c, p) in tasks:
        foot[g] |= fps[tpl]
    caps = []
    for v in range(n):
        used = sum(groups[g][0] for g in range(G) if foot[g] and v in foot[g])
        caps.append(used + rng.choice([0, 0, 0, 1, 2, 5]))
    # ensure work legality: bump budgets/quotas so load <= quota*budget
    load = [0]*G
    for (tpl, g, w, c, p) in tasks:
        load[g] += w
    for g in range(G):
        if load[g] > 0:
            if groups[g][0] == 0:
                groups[g][0] = rng.randint(1, 4)
            need = -(-load[g] // groups[g][0])
            if groups[g][1] < need:
                groups[g][1] = need
    usage = [0]*n
    foot = [set() for _ in range(G)]
    for (tpl, g, w, c, p) in tasks:
        foot[g] |= fps[tpl]
    for v in range(n):
        usage[v] = sum(groups[g][0] for g in range(G) if foot[g] and v in foot[g])
    caps = [usage[v] + rng.choice([0, 0, 0, 1, 3]) for v in range(n)]

    def query():
        return {'groups': [rng.randrange(G) for _ in range(rng.randint(0, 4))],
                'nodes': [rng.randrange(n) for _ in range(rng.randint(0, 4))],
                'tasks': [rng.randrange(D) for _ in range(rng.randint(0, 4))] if D else []}

    transactions = []
    rev = 0
    for _ in range(rng.randint(0, 12)):
        if rng.random() < 0.2:
            r = max(0, rev + rng.choice([-1, 1, 2]))
        else:
            r = rev
        edits = []
        for _ in range(rng.randint(0, 5)):
            kind = rng.choice(['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap'])
            if kind == 'move': edits.append([kind, rng.randrange(D), rng.randrange(G)])
            elif kind == 'weight': edits.append([kind, rng.randrange(D), rng.randint(1, 40)])
            elif kind == 'class': edits.append([kind, rng.randrange(D), rng.randint(0, 4)])
            elif kind == 'bind': edits.append([kind, rng.randrange(D), rng.randrange(T)])
            elif kind == 'pin': edits.append([kind, rng.randrange(D), rng.randint(0, 1)])
            elif kind == 'quota': edits.append([kind, rng.randrange(G), rng.randint(0, 12)])
            elif kind == 'budget': edits.append([kind, rng.randrange(G), rng.randint(1, 10**6)])
            else: edits.append([kind, rng.randrange(n), rng.randint(0, 40)])
        transactions.append({'revision': r, 'edits': edits, 'query': query()})
        rev += 1  # upper bound; harness only needs plausible revisions
    return {'topology': spec, 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': query(), 'transactions': transactions}

def gen_request(seed, sessions=2):
    rng = random.Random(seed)
    return {'version': 2, 'sessions': [gen_session(rng) for _ in range(sessions)]}
